-/// Retries `f` with [`RPC_RETRY_DELAYS`] backoff, returning the last error if every
-/// attempt fails. Callers decide what a failure means: startup paths that cannot
-/// continue should use [`retry_rpc_or_panic`], while long-running loops should
-/// handle the error and keep going.
-pub(crate) async fn retry_rpc<T, E, F, Fut>(op_name: impl std::fmt::Display, mut f: F) -> Result<T, E>
+/// Runs the fallible async operation `f`, re-invoking it after a fixed backoff for as
+/// long as it keeps returning `Err`. `op_name` only labels the `warn!` emitted before
+/// each retry.
+///
+/// Backoff is [`RPC_RETRY_DELAYS`]: 5s after the first failure, 15s after the second,
+/// 45s after the third. That is [`RPC_MAX_ATTEMPTS`] (4) calls to `f` and at most 65s
+/// of sleeping, chosen to outlast a 30s RPC timeout rather than pile retries on top of
+/// a node that is already hanging.
+///
+/// This function does **not** panic when the retries are exhausted: the fourth failure
+/// returns the last `Err(e)` verbatim, unwrapped and with no added context, so sentinel
+/// error strings survive the round trip. Deciding what exhaustion means is the caller's
+/// job — startup paths with no way to continue wrap this in [`retry_rpc_or_panic`],
+/// which is where the fail-fast panic lives, while long-running route loops handle the
+/// error and keep going, because a panic in a spawned task takes that route offline.
+///
+/// A `null` reply is a success here, hence `Ok`; use [`retry_rpc_opt`] if `None` should
+/// be retried instead.
+pub(crate) async fn retry_rpc<T, E, F, Fut>(
+    op_name: impl std::fmt::Display,
+    mut f: F,
+) -> Result<T, E>
 where
     F: FnMut() -> Fut,
     Fut: std::future::Future<Output = Result<T, E>>,
@@ -79,7 +96,10 @@ where
